import{_ as i,o,c as a,a4 as l}from"./chunks/framework.vNSRaLQv.js";const h=JSON.parse('{"title":"ExecutorGateway 架构说明","description":"","frontmatter":{"title":"ExecutorGateway 架构说明","date":"2026-04-29T00:00:00.000Z"},"headers":[],"relativePath":"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_executor-gateway-architecture-zh.md","filePath":"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_executor-gateway-architecture-zh.md"}'),t={name:"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_executor-gateway-architecture-zh.md"};function c(d,e,r,s,n,p){return o(),a("div",null,[...e[0]||(e[0]=[l(`<h1 id="executorgateway-架构说明" tabindex="-1">ExecutorGateway 架构说明 <a class="header-anchor" href="#executorgateway-架构说明" aria-label="Permalink to &quot;ExecutorGateway 架构说明&quot;">​</a></h1><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>HomeSense Studio 的 Workflow 不应该直接耦合某一个 CLI、某一个设备协议，或者某一个外部 Agent。</p><p>它更合理的结构是：</p><ul><li><code>WorkflowNode</code> 只声明“我要调用什么能力”</li><li><code>ExecutorGateway</code> 负责把这个能力分发到真实执行端</li><li><code>CLI / Service / Workflow / Agent</code> 只是不同的执行端类型</li></ul><p>这层设计同时借鉴了：</p><ul><li><code>dify</code> 的节点工厂与 runtime 分层</li><li><code>agentmesh</code> 的 executor / graph 执行思想</li><li><code>claude-code-agents</code> 的 tool registry / agent dispatcher 风格</li></ul><h2 id="当前实现" tabindex="-1">当前实现 <a class="header-anchor" href="#当前实现" aria-label="Permalink to &quot;当前实现&quot;">​</a></h2><p>当前系统已经具备：</p><ol><li><p><code>ExecutorGateway</code></p><ul><li><code>cli.invoke</code></li><li><code>service.invoke</code></li><li><code>workflow.run</code></li><li><code>plan.run</code></li><li><code>agent.dispatch</code> 占位</li></ul></li><li><p><code>PlanLibrary</code></p><ul><li>会读取老项目的 <code>paths.json</code></li><li>把 <code>watch_bilibili_demo</code> 这类成功路径导入成结构化 plan</li></ul></li><li><p><code>executor_call</code> Workflow 节点</p><ul><li>WorkflowRuntime 可以直接调用 <code>ExecutorGateway</code></li><li>这让 Studio 开始具备“Agent 中枢”的后端骨架</li></ul></li></ol><h2 id="为什么这很关键" tabindex="-1">为什么这很关键 <a class="header-anchor" href="#为什么这很关键" aria-label="Permalink to &quot;为什么这很关键&quot;">​</a></h2><p>这层把系统从“工作流节点直接写 mi-cli / adb-cli 调用”升级成了：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Workflow Node</span></span>
<span class="line"><span>  -&gt; ExecutorGateway</span></span>
<span class="line"><span>    -&gt; CLI / Service / Workflow / External Agent</span></span></code></pre></div><p>所以以后接：</p><ul><li><code>mi-cli</code></li><li><code>adb-cli</code></li><li><code>B站 CLI</code></li><li><code>OpenClaw</code></li><li><code>Codex</code></li><li><code>Claude Code</code></li></ul><p>时，不需要每种能力都单独发明一套节点模型。</p><h2 id="老项目-b站母路径" tabindex="-1">老项目 B站母路径 <a class="header-anchor" href="#老项目-b站母路径" aria-label="Permalink to &quot;老项目 B站母路径&quot;">​</a></h2><p>老项目里的 <code>watch_bilibili_demo</code> 现在会被：</p><ul><li>导入 <code>PlanLibrary</code></li><li>编译进 <code>compiled_knowledge_items</code></li><li>通过 <code>/api/executor-gateway/plans/:id</code> 提供结构化 preview</li></ul><p>这条路径当前的主线执行器已经切到：</p><ul><li><code>mi-cli</code>：米家场景、小爱音箱、红外控制</li><li><code>adb-cli</code>：Android TV 连接、包名检查、应用启动</li></ul><p>但这不是坏事。它恰好说明：</p><ul><li>新项目已经承接了老项目的成功经验</li><li>计划与执行器已经分离</li><li>下一步只需要补真实设备验证，不需要重写计划表达</li></ul><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><p>一句话概括：</p><p><strong>现在 HomeSense 已经有了“执行器中枢 + 计划库 + 工作流调用中枢”的骨架。</strong></p><p>后面补充真实 <code>adb-cli / mi-cli / B站 CLI</code> 时，优先是在执行器层扩容，而不是改 WorkflowRuntime 主干。<code>hami-cli</code> 仅保留为历史参考，不再作为当前设备主线。</p>`,27)])])}const _=i(t,[["render",c]]);export{h as __pageData,_ as default};
